using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Collections.Generic;using System.Security.Cryptography;using System.Text;using System.Windows.Forms;
internal sealed partial class ControlWindow {
 internal async Task RunDiscoverySmoke(string mode){try{
  Require(library.Doc.Items.Count>=5,"Latest live catalog not migrated");var prior=Common.Json.Serialize(library.Doc);var audio=Common.Json.Serialize(settings);
  if(mode=="restart"){var imported=library.Doc.Items.Single(x=>x.ResourceId=="398713");Require(imported.PreviewConfirmedSha256==null&&imported.DesktopConfirmedSha256==null&&File.Exists(imported.CoverPath)&&CurrentRun==null,"New import persistence or accidental compatibility");ClientShot(this,"discovery-restarted-home");Common.SaveNew(Path.Combine(Common.Root,"evidence/discovery-restart-passed.json"),new{cards=library.Doc.Items.Count,noPlayer=true,discoveryStateRetained=File.Exists(ResourceDiscovery.StatePath)});Close();return;}
  string fixture=LocalImport.DataRoot;await ProbeDiscovery();Require(!discoveryBusy&&discoveryOperation!=null,"Baseline discovery task");var baseline=Common.Json.Deserialize<DiscoverySummary>(Common.Json.Serialize(Common.Read(Path.Combine(discoveryOperation.Folder,"result.json"))["discovery"]));Require(baseline.FirstBaseline&&baseline.HashedBytes==0&&baseline.UnreadComplete==0,"Initial history notified or hashed");
  File.Delete(Path.Combine(Common.Root,"tests/no-auto-discovery"));StartDiscovery();string input=File.ReadAllText(Path.Combine(Common.Root,"tests/new-source.txt")).Trim();string md5;using(var f=File.OpenRead(input))using(var m=MD5.Create())md5=BitConverter.ToString(m.ComputeHash(f)).Replace("-","").ToLowerInvariant();string source=Path.Combine(fixture,"wallpaper/wpcache/dynamic",md5+".cwp");File.Copy(input,source);byte[] json=Encoding.UTF8.GetBytes("0000"+Common.Json.Serialize(new{wpId=398713,wpName=md5+".cwp",wpMd5=md5,wpType=2,action=4}));for(int i=0;i<json.Length;i++)json[i]^=0xe7;File.WriteAllBytes(Path.Combine(fixture,"cache_info/398713_fixture.dat"),json);
  var clock=System.Diagnostics.Stopwatch.StartNew();while(!discoveryHint.Text.StartsWith("发现 1 项新壁纸",StringComparison.Ordinal)){if(clock.Elapsed.TotalSeconds>28)throw new Exception("Actual known-directory watcher did not produce one verified notice: "+discoveryHint.Text);await Task.Delay(100);}
  Require(library.Doc.Items.Count==Common.Json.Deserialize<LibraryDocument>(prior).Items.Count&&CurrentRun==null,"Discovery autoimported or played");ClientShot(this,"discovery-new-notice");var ready=Common.Read(Path.Combine(discoveryOperation.Folder,"result.json"));Common.SaveNew(Path.Combine(Common.Root,"evidence/discovery-watch-ready.json"),new{result=ready,notice=discoveryHint.Text,secondsUntilNotice=clock.Elapsed.TotalSeconds,actualFileSystemWatcher=true,fixtureCopyOfExistingLegitimateLocalResource=true,noAutoImport=true,noPlayer=true});
  OpenLocalImport();await WaitCoverDialog();var scan=Common.Read(Path.Combine(importOperation.Folder,"result.json"));var candidates=CoverCandidates(scan);Require(candidates.First().Id=="398713"&&candidates.First().NewlyDiscovered&&candidates.First().DiscoveredSha256==Common.Hash(input),"New resource not first or wrong identity");foreach(ListViewItem row in importDialog.list.Items)if(((ImportCandidate)row.Tag).Id=="398713"){row.Selected=true;row.EnsureVisible();break;}await Task.Delay(150);ClientShot(importDialog,"discovery-recent-import-dialog");Common.SaveNew(Path.Combine(Common.Root,"evidence/discovery-candidates.json"),scan);
  var lazy=candidates.FirstOrDefault(c=>c.CoverReason=="选择后按需读取真实封面");Require(lazy!=null,"No delayed-cover fixture");foreach(ListViewItem row in importDialog.list.Items)if(((ImportCandidate)row.Tag).Id==lazy.Id){row.Selected=true;row.EnsureVisible();break;}await Task.Delay(150);await WaitCoverDialog();var lazyRow=importDialog.list.Items.Cast<ListViewItem>().Single(row=>((ImportCandidate)row.Tag).Id==lazy.Id);Require(((ImportCandidate)lazyRow.Tag).Cover!=null,"Selected history cover not lazily loaded");
  foreach(ListViewItem row in importDialog.list.Items)if(((ImportCandidate)row.Tag).Id=="398713"){row.Selected=true;row.EnsureVisible();break;}await importDialog.ImportSelected();Require(library.Doc.Items.Count==Common.Json.Deserialize<LibraryDocument>(prior).Items.Count+1&&CurrentRun==null,"Internal selected import failed/autoplay");var item=library.Doc.Items.Single(x=>x.ResourceId=="398713");Require(item.RegisteredSha256==Common.Hash(input)&&item.PreviewConfirmedSha256==null&&item.DesktopConfirmedSha256==null,"New import inherited compatibility");importDialog.Close();await ProbeDiscovery();var after=Common.Json.Deserialize<DiscoverySummary>(Common.Json.Serialize(Common.Read(Path.Combine(discoveryOperation.Folder,"result.json"))["discovery"]));Require(after.UnreadComplete==0&&after.HashedBytes==0,"Imported/viewed resource repeatedly notified/rehashed");Require(Common.Json.Serialize(settings)==audio,"Sound changed");
  ClientShot(this,"discovery-imported-home");Common.SaveNew(Path.Combine(Common.Root,"evidence/discovery-ui-passed.json"),new{actualWatchEvent=true,baselineHistoryNotNotified=true,newVerifiedFirst=true,lazySelectedCover=true,internalSelectedImportOnly=true,allOriginalCardsPreserved=true,currentCards=library.Doc.Items.Count,source=item.SourcePath,sha256=item.RegisteredSha256,viewedOrImportedNotNotifiedAgain=true,noAutoPlayback=true,noNewCompatibility=true,soundPreserved=true,method="internal TEST_BUILD UI handlers and private official-record fixtures; not user clicks or an actual new official download"});Close();
 }catch(Exception ex){Common.SaveNew(Path.Combine(Common.Root,"evidence/discovery-ui-failed.json"),new{error=ex.ToString()});Write("discovery-smoke-failed",new{error=ex.ToString()});Close();}}
}
